import ast
import copy
import hashlib
import json
from pathlib import Path
root=Path('/workspace'); p=json.loads((root/'proposal.json').read_text()); r=json.load(open('/tmp/runtime_contract.json'))
def check(value,s,path='"'$'"'):
    types={'object':dict,'array':list,'string':str,'boolean':bool}
    if 'type' in s: assert isinstance(value,types[s['type']]),(path,'type')
    if 'const' in s: assert value==s['const'],(path,'const')
    if 'enum' in s: assert value in s['enum'],(path,'enum')
    if isinstance(value,dict):
        assert set(s.get('required',[])) <= set(value),(path,'required')
        if s.get('additionalProperties') is False: assert set(value)<=set(s.get('properties',{})),(path,'extra')
        for k,v in value.items():
            if k in s.get('properties',{}): check(v,s['properties'][k],path+'.'+k)
    if isinstance(value,list):
        assert len(value)>=s.get('minItems',0),(path,'minItems')
        if 'items' in s:
            for i,v in enumerate(value):check(v,s['items'],path+'['+str(i)+']')
    if isinstance(value,str):assert len(value)>=s.get('minLength',0),(path,'minLength')
check(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
base=ast.parse(Path('/tmp/incumbent_source.py').read_text()); base_cls=next(n for n in base.body if isinstance(n,ast.ClassDef))
base_methods={n.name:n for n in base_cls.body if isinstance(n,ast.FunctionDef)}
def dump(v):return ast.dump(v,include_attributes=False) if isinstance(v,ast.AST) else [dump(x) for x in v]
normalized=[]
for v in p['variants']:
    file=root/v['file']; assert file.parent==root and file.suffix=='.py'
    source=file.read_text(); compile(source,str(file),'exec'); tree=ast.parse(source)
    config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    config=ast.literal_eval(config_node.value); assert config==v['config']
    cls=next(n for n in tree.body if isinstance(n,ast.ClassDef)); methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
    init=methods['__init__']; defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
    for k,value in config.items():
        default=ast.literal_eval(defaults[k]); assert default==value or tuple(value)==default,(file,k)
    for n in ast.walk(tree):
        if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for a in n.names)
        if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__','compile'}
    assert set(methods)==set(base_methods)
    for name in set(methods)-{'__init__','forward'}:assert dump(methods[name])==dump(base_methods[name]),(file,name)
    def learned_tail(node):
        i=next(i for i,n in enumerate(node.body) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='embedding_layer' for t in n.targets))
        return node.body[i:]
    assert dump(learned_tail(init))==dump(learned_tail(base_methods['__init__'])),(file,'learned construction')
    old=base_methods['forward'].body; new=methods['forward'].body
    assert dump(new[:2])==dump(old[:2])
    branch=new[2]; assert isinstance(branch,ast.If)
    assert dump(branch.body)==dump(old[2:9]),(file,'training operator sequence')
    assert dump(new[3:])==dump(old[9:]),(file,'auxiliary and readout tail')
    assert isinstance(branch.test,ast.BoolOp) and isinstance(branch.test.op,ast.Or)
    assert dump(branch.test.values[0])==dump(ast.parse('self.training',mode='eval').body)
    digest=hashlib.sha256(file.read_bytes()).hexdigest(); assert digest in v['note']
    canonical=copy.deepcopy(tree)
    for n in ast.walk(canonical):
        if isinstance(n,ast.Constant) and n.value==config['inference_support']:n.value='MODE'
    normalized.append(dump(canonical))
assert all(x==normalized[0] for x in normalized)
print('PASS: complete supplied study schema; protocol/evidence/parent IDs;3 unique standalone variants; literal CONFIG/default agreement; syntax; allowed imports/no direct I/O; module AST parity modulo execution mode; unchanged learned construction/initialization and inherited methods; exact original train-branch operators and auxiliary/readout tail; source hashes.')
print('NOT RUN: model/tensor/gradient/BF16 execution, data validation, training, performance or timing. Host gates remain prospective.')
